mapper.select:
SELECT sel.id AS selectionId, sel.course_id AS courseId, c.course_code AS courseCode, c.course_name AS courseName, tu.real_name AS teacherName, c.credit AS credit, se.semester_name AS semesterName, sel.score AS totalScore FROM course_selection sel INNER JOIN course c ON c.id = sel.course_id AND c.deleted = 0 LEFT JOIN teacher t ON t.id = c.teacher_id AND t.deleted = 0 LEFT JOIN sys_user tu ON tu.id = t.user_id AND tu.deleted = 0 LEFT JOIN semester se ON se.id = sel.semester_id AND se.deleted = 0 LEFT JOIN course_review r ON r.selection_id = sel.id WHERE sel.deleted = 0 AND sel.student_id = #{studentId} AND sel.status = 2 AND r.id IS NULL
AND sel.semester_id = #{semesterId}
ORDER BY sel.semester_id DESC, sel.id DESC

SELECT

FROM course_review r

WHERE r.student_id = #{studentId}

    AND r.semester_id = #{semesterId}

ORDER BY r.submit_time DESC, r.id DESC

SELECT c.id AS courseId, c.course_code AS courseCode, c.course_name AS courseName, tu.real_name AS teacherName, se.semester_name AS semesterName, IFNULL(ROUND(AVG(CASE WHEN r.status = 2 THEN r.average_score END), 1), 0) AS averageScore, IFNULL(ROUND(AVG(CASE WHEN r.status = 2 THEN r.score_content END), 1), 0) AS scoreContent, IFNULL(ROUND(AVG(CASE WHEN r.status = 2 THEN r.score_teaching END), 1), 0) AS scoreTeaching, IFNULL(ROUND(AVG(CASE WHEN r.status = 2 THEN r.score_attitude END), 1), 0) AS scoreAttitude, IFNULL(ROUND(AVG(CASE WHEN r.status = 2 THEN r.score_gain END), 1), 0) AS scoreGain, SUM(CASE WHEN r.status = 2 THEN 1 ELSE 0 END) AS reviewCount, (SELECT COUNT(*) FROM course_selection sel WHERE sel.course_id = c.id AND sel.status = 2 AND sel.deleted = 0) AS studentCount FROM course c LEFT JOIN teacher t ON t.id = c.teacher_id AND t.deleted = 0 LEFT JOIN sys_user tu ON tu.id = t.user_id AND tu.deleted = 0 LEFT JOIN semester se ON se.id = c.semester_id AND se.deleted = 0 LEFT JOIN course_review r ON r.course_id = c.id WHERE c.deleted = 0 AND c.teacher_id = #{teacherId}
AND c.semester_id = #{semesterId}
GROUP BY c.id, c.course_code, c.course_name, tu.real_name, se.semester_name ORDER BY c.semester_id DESC, c.id DESC

SELECT
FROM course_review r
WHERE 1 = 1
AND r.course_id = #{query.courseId}
AND r.teacher_id = #{query.teacherId}
AND r.semester_id = #{query.semesterId}
AND r.status = #{query.status}
AND (c.course_name LIKE CONCAT('%', #{query.keyword}, '%') OR c.course_code LIKE CONCAT('%', #{query.keyword}, '%') OR tu.real_name LIKE CONCAT('%', #{query.keyword}, '%'))
AND r.average_score >= 4.5
AND r.average_score >= 3.5 AND r.average_score < 4.5
AND r.average_score >= 2.5 AND r.average_score < 3.5
AND r.average_score < 2.5
ORDER BY r.submit_time DESC, r.id DESC
